-- 11 October 2026 current-affairs desk.
-- Late 9 October and substantive 10 October releases, verified against the
-- cited primary official publications before publication.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-10-11-ngopv-shreyas-launch$$, $$2026-10-11$$,
  $$Navy's next-generation offshore patrol vessel Shreyas launched at GRSE$$,
  $$Yard 3040, named Shreyas, was launched at Garden Reach Shipbuilders and Engineers in Kolkata as a next-generation offshore patrol vessel for the Indian Navy.$$,
  $$This is a defence-indigenisation item. It connects domestic shipbuilding with the Navy's peacetime and operational roles, including surveillance, search and rescue, humanitarian assistance and disaster relief, and anti-piracy.$$,
  $$An offshore patrol vessel is designed for sustained operations in maritime zones rather than for a single specialised combat task. The release says NGOPVs are being built concurrently at GRSE in Kolkata and Goa Shipyard Limited, and will augment existing OPV/NOPV capability. A ship launch is a construction milestone; it is not the same as commissioning, when a completed vessel formally joins naval service.$$,
  $$Launch of Next Generation Offshore Patrol Vessel (Yard 3040, Shreyas) at GRSE, Kolkata$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321795&lang=1&reg=3$$,
  $$Ministry of Defence / Press Information Bureau$$, $$2026-10-10$$,
  $$["Shreyas is Yard 3040, a Next Generation Offshore Patrol Vessel (NGOPV).","It was launched at GRSE, Kolkata.","NGOPVs are also under construction at Goa Shipyard Limited.","The stated roles include maritime surveillance, search and rescue, offshore-asset protection, HADR and anti-piracy."]$$::jsonb,
  $$[{"question":"Is launching a naval vessel the same as commissioning it?","answer":"No. Launching is a shipbuilding milestone; commissioning formally inducts a completed vessel into service."},{"question":"Name one non-war role listed for the NGOPVs.","answer":"Search and rescue, HADR, maritime surveillance, offshore-asset protection or anti-piracy."}]$$::jsonb,
  $${"title":"From shipyard launch to maritime capability","steps":["Indian shipyards build an indigenous patrol vessel.","Launching moves the hull into the next construction and fitting-out stages.","Trials and acceptance work precede formal commissioning.","The commissioned ship can support surveillance, rescue and security missions."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-india-ai-agri-food-systems-meeting$$, $$2026-10-11$$,
  $$India hosts UN initiative meeting on AI for agri-food systems$$,
  $$The Telecommunication Engineering Centre and ICAR hosted the second meeting of the UN Global Initiative on AI for Agri-Food Systems alongside India Mobile Congress 2026, advancing work on trustworthy, interoperable and farmer-centred digital agriculture.$$,
  $$This is a science-and-technology and agriculture-governance item. It tests the link between AI, IoT, data standards and precision agriculture, while showing that a global initiative or meeting is a collaboration platform, not a new subsidy or a binding agricultural law.$$,
  $$The initiative is coordinated by the International Telecommunication Union with collaboration from FAO, IFAD and WFP. The meeting followed the first meeting in Rome and considered use cases, interoperable systems, governance and work-stream priorities. In practice, AI and connected devices can support advisories, disease detection, resource management and traceability, but their policy value depends on reliable data, affordability, safeguards and farmer usability.$$,
  $$Second Meeting of Global Initiative on AI for Agri-Food Systems (GI-AI4FS) held at IMC 2026 in New Delhi$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321784&lang=1&reg=3$$,
  $$Telecommunication Engineering Centre, Department of Telecommunications / ICAR / Press Information Bureau$$, $$2026-10-10$$,
  $$["GI-AI4FS is a UN Global Initiative on AI for agri-food systems.","The 10 October meeting was hosted alongside India Mobile Congress 2026 in New Delhi.","TEC of the Department of Telecommunications and ICAR jointly hosted the meeting.","ITU coordinates the initiative in collaboration with FAO, IFAD and WFP."]$$::jsonb,
  $$[{"question":"Which UN specialised agency coordinates GI-AI4FS?","answer":"The International Telecommunication Union (ITU)."},{"question":"Does this meeting itself create a compulsory AI scheme for all farmers?","answer":"No. It is a forum for cooperation, standards, governance and practical collaboration."}]$$::jsonb,
  $${"title":"AI for agri-food systems: policy chain","steps":["Farm and food-system problems create demand for digital solutions.","Sensors, data and AI can generate advisories or improve traceability.","Common standards and governance help systems work together safely.","Pilots and farmer-centred deployment determine real-world usefulness."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-nba-seed-sector-abs-disbursement$$, $$2026-10-11$$,
  $$National Biodiversity Authority distributes seed-sector benefit-sharing funds$$,
  $$The National Biodiversity Authority disbursed ₹2.02 crore in Access and Benefit-Sharing funds from seed-sector companies to 27 States and three Union Territories for biodiversity conservation, sustainable use and community welfare.$$,
  $$This is a biodiversity-governance item. It tests Access and Benefit Sharing, the roles of the NBA, State Biodiversity Boards and Union Territory Biodiversity Councils, and India's implementation of fair benefit sharing from the use of biological resources.$$,
  $$ABS is not a general tax on farmers. It is the legal mechanism through which benefits from accessing and using biological resources and associated knowledge are shared fairly under the biodiversity framework. For this distribution, where individual benefit claimers could not be identified, the Authority used approved distribution modalities and apportioned funds using cultivation-area data. The release links the framework to the Biological Diversity Act, 2002 and the Kunming-Montreal Global Biodiversity Framework.$$,
  $$NBA Disburses ₹2.02 Crore of ABS Funds from Seed Sector to Support Biodiversity Conservation and Community Well-Being$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321791&lang=1&reg=3$$,
  $$National Biodiversity Authority, Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-10-10$$,
  $$["The NBA disbursed ₹2.02 crore from seed-sector ABS contributions.","The allocation covered 27 States and three Union Territories.","The release says cumulative NBA ABS disbursement reached ₹202 crore.","The framework supports the Biological Diversity Act, 2002 and fair benefit sharing from use of biological resources."]$$::jsonb,
  $$[{"question":"What does ABS mean in biodiversity governance?","answer":"Access and Benefit Sharing: fair and equitable sharing of benefits arising from use of biological resources and associated knowledge under the applicable framework."},{"question":"Which national body made this disbursement?","answer":"The National Biodiversity Authority (NBA)."}]$$::jsonb,
  $${"title":"How seed-sector ABS can reach local biodiversity institutions","steps":["Use of biological resources generates an applicable ABS contribution.","The NBA applies the approved benefit-sharing framework.","State Boards and UT Biodiversity Councils receive apportioned funds.","Funds can strengthen registers, conservation, sustainable use and local participation."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-aitiga-review-timebound-deliverables$$, $$2026-10-11$$,
  $$ASEAN and India set time-bound work for review of trade-in-goods agreement$$,
  $$At the 15th ASEAN-India Trade in Goods Agreement Joint Committee meeting, the sides directed sub-committees to speed up pending review chapters through time-bound deliverables and scheduled the next review meeting for January 2027 in India.$$,
  $$This is an international-trade item. It is useful for questions on ASEAN, trade agreements, rules of origin, national treatment and the difference between treaty review negotiations and a concluded or newly notified trade agreement.$$,
  $$AITIGA is the ASEAN-India Trade in Goods Agreement. The official release records that three of its eight sub-committees met alongside the Joint Committee: legal and institutional issues, national treatment on market access, and rules of origin. The meeting did not announce a completed replacement agreement; it advanced the ongoing review and asked for progress on pending chapters.$$,
  $$15th Meeting of ASEAN-India Trade in Goods Agreement (AITIGA) Joint Committee held during 6-9 October 2026$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321209&lang=1&reg=3$$,
  $$Department of Commerce, Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-10-09$$,
  $$["AITIGA stands for ASEAN-India Trade in Goods Agreement.","The 15th Joint Committee met from 6 to 9 October 2026 at the ASEAN Secretariat in Jakarta in hybrid mode.","The meeting asked sub-committees to expedite pending review chapters with time-bound deliverables.","The next Joint Committee meeting is scheduled for January 2027 in India."]$$::jsonb,
  $$[{"question":"What does AITIGA cover?","answer":"Trade in goods between India and ASEAN under their agreement; the reported work concerns its ongoing review."},{"question":"Did the 15th meeting announce a final new agreement?","answer":"No. It recorded progress and directions for the continuing review negotiations."}]$$::jsonb,
  $${"title":"How an existing trade agreement is reviewed","steps":["Parties identify chapters requiring modernisation or resolution.","Technical sub-committees examine issues such as rules of origin and market access.","The Joint Committee gives political and procedural direction.","A completed negotiated text would still require the relevant adoption process."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-india-post-blue-dart-parcel-agreement$$, $$2026-10-11$$,
  $$India Post and Blue Dart agree to expand parcel last-mile delivery$$,
  $$The Department of Posts and Blue Dart signed an agreement for India Post Parcel services, combining India Post's nationwide network with private express-logistics operations for parcels, including remote-area delivery, tracking and OTP-based authentication.$$,
  $$This is a logistics and public-service delivery item. It links the postal network to e-commerce, last-mile connectivity and technology-enabled parcel services; it is an operational partnership, not a privatisation of the Department of Posts.$$,
  $$The release says Blue Dart will use India Post's network across urban, semi-urban, rural and underserved areas. Services are to include prepaid and cash-on-delivery parcels, OTP delivery authentication and real-time tracking. India Post operates more than 1.64 lakh post offices, so the agreement illustrates how a public network can be used with a private logistics provider to extend delivery reach.$$,
  $$Department of Posts and Blue Dart Express Limited Sign Agreement for India Post Parcel Services Across India$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321512&lang=1&reg=3$$,
  $$Department of Posts, Ministry of Communications / Press Information Bureau$$, $$2026-10-09$$,
  $$["The agreement is between the Department of Posts and Blue Dart Express Limited.","It covers India Post Parcel services across India.","Stated features include prepaid and COD parcels, OTP authentication and real-time tracking.","The release describes the postal network as more than 1.64 lakh post offices."]$$::jsonb,
  $$[{"question":"Which ministry houses the Department of Posts?","answer":"The Ministry of Communications."},{"question":"Does the agreement mean India Post has been privatised?","answer":"No. It is an operational partnership using the Department's network for parcel services."}]$$::jsonb,
  $${"title":"Last-mile parcel delivery partnership","steps":["A private express operator needs wider delivery reach.","India Post contributes its nationwide postal network.","Technology supports tracking and OTP-based handover.","Customers and e-commerce sellers can access broader parcel coverage."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-pmddky-first-year-implementation$$, $$2026-10-11$$,
  $$PM Dhan-Dhaanya Krishi Yojana completes its first year of district action$$,
  $$A first-year official review of the PM Dhan-Dhaanya Krishi Yojana reported that all 100 selected districts had prepared and begun implementing District Action Plans, using convergence across Central and State schemes.$$,
  $$This is an agriculture and cooperative-federalism item. It tests district-level planning, scheme convergence, outcome monitoring and the difference between a programme's implementation review and the launch of a fresh scheme.$$,
  $$PMDDKY is a six-year initiative from 2025-26 for 100 Aspirational Agricultural Districts. Districts were selected using low productivity, low cropping intensity and low agricultural-credit disbursement, with State and UT agricultural characteristics also considered. Implementation has three levels: a district committee chaired by the District Collector or DM, a State committee chaired by the Chief Secretary, and national oversight committees. The dashboard tracks 121 indicators across 36 schemes.$$,
  $$Prime Minister Dhan-Dhaanya Krishi Yojana: One Year of Focused Agricultural Development Across 100 Districts$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321731&lang=1&reg=3$$,
  $$PIB Research / Ministry of Agriculture and Farmers Welfare$$, $$2026-10-10$$,
  $$["PMDDKY was approved for six years beginning in 2025-26.","It focuses on 100 Aspirational Agricultural Districts.","All 100 districts had prepared District Action Plans according to the first-year review.","The programme tracks 121 indicators across 36 schemes."]$$::jsonb,
  $$[{"question":"Who heads the district-level PMDDKY committee?","answer":"The District Collector or District Magistrate."},{"question":"Which three core indicators are named for district selection?","answer":"Low productivity, low cropping intensity and lower agricultural-credit disbursement."}]$$::jsonb,
  $${"title":"District convergence under PMDDKY","steps":["A district is identified through agricultural-development indicators.","The district committee prepares a locally grounded action plan.","Central and State schemes converge around that plan.","Indicator-based monitoring supports review by State and national bodies."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-ipu-arusha-communique-and-resolutions$$, $$2026-10-11$$,
  $$153rd Inter-Parliamentary Union Assembly adopts Arusha Communiqué$$,
  $$The 153rd Inter-Parliamentary Union Assembly in Arusha adopted the Arusha Communiqué and resolutions on disability inclusion and urgent parliamentary action on climate-related disasters; Australia's Milton Dick was elected the next IPU President.$$,
  $$This is a global-governance and parliamentary-diplomacy item. It tests the Inter-Parliamentary Union as an international organisation of national parliaments, the difference between its resolutions and binding domestic law, and the participation of Indian parliamentary delegations.$$,
  $$The Assembly was held in Arusha, Tanzania, from 5 to 9 October. India had three allocated votes in the presidential election, cast by members of its delegation. The adopted texts set out parliamentary positions and cooperation priorities; they do not automatically amend India's statutes or create an enforceable international treaty.$$,
  $$Indian Parliamentary Delegation at the 153rd Inter-Parliamentary Union Assembly, Arusha$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321679&lang=1&reg=3$$,
  $$Rajya Sabha Secretariat / Press Information Bureau$$, $$2026-10-10$$,
  $$["The 153rd IPU Assembly was held in Arusha, Tanzania, from 5 to 9 October 2026.","The Assembly adopted the Arusha Communiqué.","It adopted resolutions on disability inclusion and climate-related disasters and resilience.","Milton Dick, Speaker of Australia's House of Representatives, was elected the next IPU President."]$$::jsonb,
  $$[{"question":"What is the IPU?","answer":"The Inter-Parliamentary Union, an international organisation that brings together national parliaments."},{"question":"Does an IPU resolution automatically change Indian law?","answer":"No. It expresses parliamentary positions and cooperation priorities; domestic legal change follows India's own constitutional processes."}]$$::jsonb,
  $${"title":"From national parliaments to an IPU assembly outcome","steps":["National parliaments send delegations to the IPU.","Delegates debate common parliamentary and global issues.","The Assembly adopts communiqués or resolutions and elects office-bearers.","Each country separately considers any follow-up within its own legal system."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-11-nasha-mukt-yuva-abhiyan-month-one$$, $$2026-10-11$$,
  $$MY Bharat and NSS complete first month of 100-week Nasha Mukt Yuva campaign$$,
  $$MY Bharat and the National Service Scheme completed the first month of the 100-Week Sankalp Abhiyan under Nasha Mukt Yuva Abhiyan, reporting a nationwide Yuva Sanwad Mela across 200 designated institutions and their adopted communities.$$,
  $$This is a youth-development and public-health-prevention item. It links MY Bharat and NSS with community mobilisation against substance misuse, and is useful for distinguishing awareness and referral work from clinical treatment or criminal-law enforcement.$$,
  $$The first month's theme was 'My Health, My Pride'. The release records 1,06,855 participants across 15 NSS Regional Directorates and reports youth dialogues, awareness stalls and cultural activities. It describes the next month's theme as 'Fit Youth, Addiction-Free Youth'. This is an implementation update for an ongoing campaign, not a new standalone prohibition law.$$,
  $$MY Bharat-NSS concludes first month of Nasha Mukt Yuva Abhiyan with nationwide Yuva Sanwad Mela$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2321739&lang=1&reg=3$$,
  $$Ministry of Youth Affairs and Sports / Press Information Bureau$$, $$2026-10-10$$,
  $$["The activity is part of the 100-Week Sankalp Abhiyan under Nasha Mukt Yuva Abhiyan.","MY Bharat and the National Service Scheme led the reported outreach.","The first-month Yuva Sanwad Mela covered 200 designated institutions and their adopted communities.","The release reports activity across 15 NSS Regional Directorates."]$$::jsonb,
  $$[{"question":"Which two youth institutions led the reported Yuva Sanwad Mela?","answer":"MY Bharat and the National Service Scheme (NSS)."},{"question":"Is an awareness campaign a substitute for addiction treatment?","answer":"No. It supports prevention, dialogue and connection to help; treatment requires appropriate health and counselling services."}]$$::jsonb,
  $${"title":"Youth-led prevention pathway","steps":["MY Bharat and NSS organise local youth engagement.","Dialogues and awareness activities address substance-use risks.","Communities can identify information and support needs.","Prevention messaging complements professional health and counselling services."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-10-11-ngopv-shreyas-launch$$,
  $$2026-10-11-india-ai-agri-food-systems-meeting$$,
  $$2026-10-11-nba-seed-sector-abs-disbursement$$,
  $$2026-10-11-aitiga-review-timebound-deliverables$$,
  $$2026-10-11-india-post-blue-dart-parcel-agreement$$,
  $$2026-10-11-pmddky-first-year-implementation$$,
  $$2026-10-11-ipu-arusha-communique-and-resolutions$$,
  $$2026-10-11-nasha-mukt-yuva-abhiyan-month-one$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
